inline const FPC *GetFPC(const void *buf) {
  return ::flatbuffers::GetRoot<FPC>(buf);
}

inline const FPC *GetSizePrefixedFPC(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<FPC>(buf);
}

inline const char *FPCIdentifier() {
  return "$FPC";
}

inline bool FPCBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FPCIdentifier());
}

inline bool SizePrefixedFPCBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FPCIdentifier(), true);
}

template <bool B = false>
inline bool VerifyFPCBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<FPC>(FPCIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedFPCBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<FPC>(FPCIdentifier());
}

inline void FinishFPCBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<FPC> root) {
  fbb.Finish(root, FPCIdentifier());
}

inline void FinishSizePrefixedFPCBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<FPC> root) {
  fbb.FinishSizePrefixed(root, FPCIdentifier());
}

inline std::unique_ptr<FPCT> UnPackFPC(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<FPCT>(GetFPC(buf)->UnPack(res));
}

inline std::unique_ptr<FPCT> UnPackSizePrefixedFPC(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<FPCT>(GetSizePrefixedFPC(buf)->UnPack(res));
}

